# -*- coding: utf-8 -*-
OT_DAYS_8 = [
{"day":164,"book":"Hosea","ref":"Hosea 1-5","title":"A Marriage That Mirrors Israel's Unfaithfulness",
 "chapters":[
  ("Hos 1","God commands Hosea to marry the unfaithful Gomer as a living picture of Israel's spiritual adultery, and their children's symbolic names foretell coming judgment."),
  ("Hos 2","God describes His pursuit of unfaithful Israel through both discipline and tender wooing back into covenant relationship."),
  ("Hos 3","Hosea is commanded to buy back and restore his unfaithful wife, dramatizing God's redemptive love for wayward Israel."),
  ("Hos 4","God indicts Israel for its lack of true knowledge of Him, resulting in pervasive moral and spiritual corruption among priests and people alike."),
  ("Hos 5","God pronounces judgment on both Israel and Judah's leaders for their persistent unfaithfulness and refusal to genuinely seek Him."),
 ],
 "themes":["God's pursuing love persists even toward those who have been unfaithful.","Genuine spiritual knowledge of God, not mere religious activity, is what He desires most."],
 "expositor":("kaiser","Kaiser observed that Hosea's own painful marriage to an unfaithful wife, commanded by God as a living illustration, gave the prophet unusually personal, firsthand insight into the anguish behind God's own wounded love for unfaithful Israel."),
 "reflect":"Is there someone in your life whose wandering has cost you real anguish, similar to what Hosea experienced and what God describes toward Israel?"},

{"day":165,"book":"Hosea","ref":"Hosea 6-10","title":"Mercy, Not Sacrifice",
 "chapters":[
  ("Hos 6","God laments that Israel's repentance is often shallow and temporary, 'like the morning mist,' desiring genuine loyalty rather than mere ritual sacrifice."),
  ("Hos 7","God describes Israel's political instability and spiritual unfaithfulness as a people who call to Egypt and Assyria for help rather than to Him."),
  ("Hos 8","Israel's manufactured idols and reliance on foreign alliances are condemned as a direct rejection of God's kingship."),
  ("Hos 9-10","God describes coming judgment and exile as the harvest of Israel's long history of spiritual unfaithfulness, comparing them to a luxuriant but ultimately fruitless vine."),
 ],
 "themes":["Superficial, temporary repentance falls short of the genuine, lasting loyalty God desires.","Seeking security in foreign alliances rather than God reflects a deeper failure of trust."],
 "expositor":("kaiser","Kaiser noted that Hosea 6:6 -- 'I desire mercy, not sacrifice' -- quoted twice by Jesus in the Gospels, shows that ritual religious performance has never been an adequate substitute for genuine, heart-level covenant loyalty."),
 "reflect":"Is there an area where you've substituted religious activity for the genuine mercy and loyalty God actually desires?"},

{"day":166,"book":"Hosea","ref":"Hosea 11-14","title":"How Can I Give You Up?",
 "chapters":[
  ("Hos 11","God recalls His tender, fatherly love in bringing Israel out of Egypt, expressing genuine anguish over having to discipline a beloved but wayward child."),
  ("Hos 12-13","God reviews Israel's history of deception since Jacob, warning that their pride and idolatry will result in inevitable judgment."),
  ("Hos 14","The book closes with a tender invitation to genuine repentance and a promise of full restoration, healing, and renewed blessing for those who return to the LORD."),
 ],
 "themes":["God's discipline of His people flows from real anguish, not cold detachment.","Genuine repentance is met with full, generous restoration, not merely grudging acceptance."],
 "expositor":("kaiser","Kaiser observed that Hosea 11's picture of God as an anguished parent -- 'how can I give you up' -- reveals that divine judgment is never separate from divine love, even when discipline becomes genuinely necessary."),
 "reflect":"Hosea 14 closes with a tender invitation to return. Is there an area where you've assumed God's response to your failure would be cold rather than the warm restoration this chapter promises?"},

{"day":167,"book":"Joel","ref":"Joel 1-3","title":"Rend Your Heart, Not Your Garments",
 "chapters":[
  ("Joel 1","A devastating locust plague strikes Judah, and Joel calls the nation to genuine mourning and repentance in response."),
  ("Joel 2","Joel describes the coming 'day of the LORD' in vivid terms, while extending a heartfelt call to 'rend your heart, not your garments' and promising God's compassionate restoration for genuine repentance."),
  ("Joel 3","God promises to judge the nations for their treatment of His people, and closes with the hopeful vision of Judah's lasting restoration and blessing."),
 ],
 "themes":["Genuine repentance requires an inward change of heart, not merely outward religious gestures.","God's judgment and God's promised restoration exist together throughout Joel's prophecy."],
 "expositor":("kaiser","Kaiser noted that Joel 2:28's promise of the Spirit poured out 'on all people' -- later quoted by Peter at Pentecost -- shows this ancient prophecy of local disaster ultimately pointing toward a far greater, universal outpouring of God's presence fulfilled in the church."),
 "reflect":"Joel calls for 'rending your heart, not your garments.' Is there an area where your response to conviction has been more outward performance than genuine inward change?"},

{"day":168,"book":"Amos","ref":"Amos 1-5","title":"Let Justice Roll Like a River",
 "chapters":[
  ("Amos 1-2","Amos pronounces judgment on surrounding nations for their brutality, before turning the same scrutiny directly onto Israel's own injustice and complacent religious hypocrisy."),
  ("Amos 3","Amos declares that God's unique relationship with Israel actually increases, rather than decreases, their accountability for injustice."),
  ("Amos 4","Amos rebukes Israel's wealthy for their comfortable exploitation of the poor, and notes that repeated warnings through hardship still failed to produce genuine repentance."),
  ("Amos 5","Amos delivers a passionate call for genuine justice to 'roll on like a river,' rejecting empty religious festivals divorced from ethical living."),
 ],
 "themes":["Privilege and unique relationship with God increase, rather than decrease, moral accountability.","Genuine worship must be inseparably connected to practical justice for the vulnerable."],
 "expositor":("kaiser","Kaiser observed that Amos 5:24's call for justice to 'roll on like a river' -- later famously quoted by Martin Luther King Jr. -- captures the prophetic conviction that authentic worship of God can never be divorced from tangible justice toward others."),
 "reflect":"Is there a way your own worship practices could become more visibly connected to practical justice or care for the vulnerable around you?"},

{"day":169,"book":"Amos","ref":"Amos 6-9","title":"Ripe for Judgment, Promised Restoration",
 "chapters":[
  ("Amos 6","Amos condemns the complacent, luxury-obsessed leaders of Israel who remain indifferent to the nation's impending downfall."),
  ("Amos 7-8","Through a series of visions -- locusts, fire, a plumb line, a basket of ripe fruit -- Amos illustrates Israel's ripened readiness for judgment, while facing personal opposition from a compromised priest."),
  ("Amos 9","The book closes with a surprising final promise of future restoration for a repentant, remnant Israel, despite everything preceding it."),
 ],
 "themes":["Comfortable complacency amid injustice provokes serious prophetic warning.","Even after extensive warning and judgment, God's ultimate purpose includes future restoration for a repentant remnant."],
 "expositor":("davis","Dale Ralph Davis-style analysis of Amos' visions in chapters 7-8 notes that the image of 'ripe fruit' signals a nation that has reached the full measure of its accountability -- judgment delayed is not judgment denied."),
 "reflect":"Is there an area of comfortable complacency in your own life that Amos' warnings might be calling you to address before it 'ripens' further?"},

{"day":170,"book":"Obadiah","ref":"Obadiah 1","title":"Pride Before a Fall",
 "chapters":[
  ("Obad 1","Obadiah pronounces judgment on Edom for their prideful, opportunistic betrayal and violence against their relative nation Judah during its time of disaster, promising eventual restoration and justice for God's people."),
 ],
 "themes":["Pride and opportunistic betrayal of the vulnerable provoke serious divine judgment.","God holds even distantly related, historically hostile nations accountable for their treatment of His people."],
 "expositor":("kaiser","Kaiser observed that Edom's specific sin condemned in Obadiah wasn't direct attack but standing aloof and even profiting from Judah's disaster -- showing that passive indifference or opportunism toward someone else's suffering carries real moral weight before God."),
 "reflect":"Is there a situation where you've stood by passively, or even benefited, from someone else's hardship rather than actively helping?"},

{"day":171,"book":"Jonah","ref":"Jonah 1-4","title":"Grace for the Enemy, Anger for the Prophet",
 "chapters":[
  ("Jonah 1","Jonah flees from God's call to preach to Nineveh, is caught in a storm, and is swallowed by a great fish after being thrown overboard."),
  ("Jonah 2","From inside the fish, Jonah prays a psalm of repentance and thanksgiving, acknowledging God's authority over his circumstances."),
  ("Jonah 3","Jonah finally obeys and preaches to Nineveh, resulting in the entire city's remarkable, immediate repentance."),
  ("Jonah 4","Jonah, angry rather than joyful at Nineveh's repentance, receives God's gentle rebuke about His compassion extending even to Israel's enemies."),
 ],
 "themes":["Fleeing from God's call doesn't remove us from His sovereign reach.","God's compassion can extend further than our own willingness to extend it toward others."],
 "expositor":("kaiser","Kaiser noted that Jonah's anger at Nineveh's repentance in chapter 4 -- wanting God's judgment more than God's mercy for his enemies -- exposes a nationalistic resentment that the book deliberately holds up for the reader's own self-examination."),
 "reflect":"Is there a group of people whose potential repentance or blessing you'd secretly resent, the way Jonah resented Nineveh's?"},

{"day":172,"book":"Micah","ref":"Micah 1-4","title":"Swords into Plowshares",
 "chapters":[
  ("Micah 1","Micah announces coming judgment on both Israel and Judah's capital cities for their pervasive idolatry."),
  ("Micah 2","Micah condemns the wealthy for their exploitative seizure of land and homes from the vulnerable."),
  ("Micah 3","Micah confronts corrupt leaders, prophets, and priests who exploit their positions for personal gain while claiming God's protection."),
  ("Micah 4","Micah envisions a future day when nations will stream to God's mountain for instruction, and swords will be beaten into plowshares."),
 ],
 "themes":["Exploiting the vulnerable for personal gain provokes serious prophetic confrontation.","God's future kingdom promises genuine, worldwide peace, not merely local political stability."],
 "expositor":("kaiser","Kaiser observed that Micah's vision of swords beaten into plowshares in chapter 4 closely parallels Isaiah 2's nearly identical prophecy, suggesting this vision of ultimate peace was a shared, foundational hope across multiple prophetic voices of the same era."),
 "reflect":"Is there a form of 'exploiting the vulnerable' -- even in small, everyday ways -- that Micah's warnings might be calling you to examine in your own life?"},

{"day":173,"book":"Micah","ref":"Micah 5-7","title":"Act Justly, Love Mercy, Walk Humbly",
 "chapters":[
  ("Micah 5","Micah delivers his celebrated prophecy naming Bethlehem as the birthplace of a future ruler whose origins are 'from of old, from ancient times' -- directly fulfilled in Christ's birth."),
  ("Micah 6","Micah's famous summary of true religion -- 'act justly, love mercy, and walk humbly with your God' -- rejects empty ritual in favor of genuine covenant faithfulness."),
  ("Micah 7","Despite describing pervasive societal corruption, the book closes with confident hope in God's willingness to forgive and His unwavering covenant faithfulness."),
 ],
 "themes":["God's specific prophecies, like naming Bethlehem centuries in advance, demonstrate remarkable predictive accuracy.","True religion is defined by justice, mercy, and humility, not empty ritual observance."],
 "expositor":("kaiser","Kaiser noted that Micah 6:8's summary of what God requires -- justice, mercy, humility -- functions as one of the Old Testament's clearest, most concise definitions of authentic faith, deliberately rejecting the idea that elaborate sacrifice alone could satisfy God's actual requirements."),
 "reflect":"Of Micah 6:8's three requirements -- justice, mercy, humility -- which do you most need to grow in right now?"},

{"day":174,"book":"Nahum","ref":"Nahum 1-3","title":"Nineveh's Second, Final Warning",
 "chapters":[
  ("Nahum 1","Nahum describes God as both patient and powerfully just, slow to anger yet fully capable of decisive judgment against persistent evil."),
  ("Nahum 2","Nahum vividly describes the coming, decisive military defeat of Nineveh, capital of the brutal Assyrian empire."),
  ("Nahum 3","Nahum pronounces Nineveh's well-deserved downfall for its extensive violence, cruelty, and exploitation of other nations."),
 ],
 "themes":["God's patience with evil, though real, is not indefinite or without eventual consequence.","Persistent, unrepentant cruelty toward others eventually meets God's decisive justice."],
 "expositor":("kaiser","Kaiser observed that Nahum functions as a kind of sequel to Jonah -- generations after Nineveh's repentance under Jonah's preaching, the city had returned fully to its former brutality, showing that repentance in one generation doesn't guarantee faithfulness in the next."),
 "reflect":"Is there a positive change from an earlier season of your life that you need to make sure hasn't quietly reversed, the way Nineveh's repentance eventually did?"},

{"day":175,"book":"Habakkuk","ref":"Habakkuk 1-3","title":"The Righteous Will Live by Faith",
 "chapters":[
  ("Hab 1","Habakkuk honestly questions God about the injustice he observes, and struggles further when told God will use the even more wicked Babylonians as His instrument of judgment."),
  ("Hab 2","God responds that 'the righteous person will live by his faithfulness,' and pronounces a series of woes against Babylon's own pride and violence."),
  ("Hab 3","Habakkuk's prayer closes with a powerful declaration of trust in God, resolving to rejoice in Him even if every visible sign of blessing were to disappear entirely."),
 ],
 "themes":["Honestly questioning God about injustice can be a genuine, faith-filled response, not a lack of faith.","Trust in God's character can remain settled even without full answers to our hardest questions."],
 "expositor":("ferguson","Ferguson observed that Habakkuk's progression -- from confused questioning to settled worship -- models a pattern of faith that doesn't require every question answered before genuine trust and even joy in God become possible."),
 "reflect":"Habakkuk resolved to rejoice in God even if every visible blessing disappeared. What would that kind of unconditional trust look like in your own current circumstances?"},

{"day":176,"book":"Zephaniah","ref":"Zephaniah 1-3","title":"God Will Rejoice Over You With Singing",
 "chapters":[
  ("Zeph 1","Zephaniah announces the sweeping, coming 'day of the LORD' as judgment on Judah's idolatry, complacency, and injustice."),
  ("Zeph 2","Zephaniah pronounces judgment on surrounding nations, while calling Judah's humble remnant to seek righteousness and humility before judgment falls."),
  ("Zeph 3","Despite describing Jerusalem's corrupt leadership, the book closes with a beautiful, tender promise of restoration, where God Himself will rejoice over His people 'with singing.'"),
 ],
 "themes":["Complacency, assuming God is indifferent to our conduct, provokes serious warning throughout Scripture.","God's ultimate plan for His people includes His own joyful delight over them, not just their obligation toward Him."],
 "expositor":("kaiser","Kaiser noted that Zephaniah 3:17's picture of God rejoicing over His people 'with singing' offers one of Scripture's most tender, often overlooked images of God's affection -- not a distant judge merely tolerating His people, but a Father who delights in them."),
 "reflect":"Does your current image of God feel more like a distant judge tolerating you, or a Father who delights in you the way Zephaniah 3:17 describes?"},

{"day":177,"book":"Haggai","ref":"Haggai 1-2","title":"Consider Your Ways",
 "chapters":[
  ("Hag 1","Haggai confronts the returned exiles for prioritizing their own comfortable homes over rebuilding God's temple, and the people respond with renewed obedience."),
  ("Hag 2","Haggai encourages the discouraged builders that the temple's future glory will exceed its former splendor, and promises God's blessing will follow their renewed obedience."),
 ],
 "themes":["Prioritizing personal comfort over God's clear calling invites His direct confrontation.","Present discouragement doesn't preclude a greater future glory than what came before."],
 "expositor":("kaiser","Kaiser observed that Haggai's rebuke -- pointing out the people's paneled houses alongside God's ruined temple -- exposes how easily personal comfort can quietly become prioritized over God's more important, if less immediately rewarding, work."),
 "reflect":"Is there a 'temple' -- something important to God's purposes -- that you've deprioritized in favor of your own comfort or convenience?"},

{"day":178,"book":"Zechariah","ref":"Zechariah 1-5","title":"Not by Might, But by My Spirit",
 "chapters":[
  ("Zech 1","Zechariah calls the returned exiles to genuine repentance, followed by a series of night visions beginning with horsemen patrolling the earth."),
  ("Zech 2","A vision of a measuring line promises Jerusalem's future expansion and God's own glorious presence as her protection."),
  ("Zech 3","A vision of the high priest Joshua being cleansed from filthy garments pictures God's gracious removal of guilt in preparation for future restoration."),
  ("Zech 4","A vision of a golden lampstand fed by olive trees encourages that the temple rebuilding will succeed 'not by might nor by power, but by my Spirit.'"),
  ("Zech 5","Visions of a flying scroll and a woman in a basket picture the removal of sin from the land."),
 ],
 "themes":["God's work often succeeds through His Spirit's power rather than human strength or strategy alone.","God graciously removes guilt in preparation for renewed purpose and calling."],
 "expositor":("kaiser","Kaiser observed that Zechariah 4:6's declaration -- 'not by might nor by power, but by my Spirit' -- addressed the returned exiles' realistic discouragement over their limited resources, reminding them that God's work was never meant to depend on human strength in the first place."),
 "reflect":"Is there a task or calling where you've been relying more on your own strength or resources than on God's Spirit?"},

{"day":179,"book":"Zechariah","ref":"Zechariah 6-10","title":"A King, Humble and Riding on a Donkey",
 "chapters":[
  ("Zech 6","A vision of four chariots patrolling the earth is followed by a symbolic crowning of the high priest Joshua, pointing toward a future priest-king."),
  ("Zech 7-8","Zechariah addresses questions about fasting, calling for genuine justice and mercy over empty ritual, and promises a future of joyful restoration for Jerusalem."),
  ("Zech 9","Zechariah delivers a striking messianic prophecy of a coming king who is 'righteous and victorious,' yet 'humble and riding on a donkey' -- fulfilled precisely at Jesus' triumphal entry."),
  ("Zech 10","God promises to strengthen and restore His scattered people, gathering them back from among the nations."),
 ],
 "themes":["Genuine justice and mercy matter more to God than empty religious ritual, even fasting.","Old Testament prophecy anticipated the Messiah's humble, peaceful arrival with striking specific detail."],
 "expositor":("kaiser","Kaiser noted that Zechariah 9:9's prophecy of a king 'humble and riding on a donkey' was fulfilled with remarkable precision at Jesus' triumphal entry into Jerusalem, deliberately choosing that exact means of arrival to fulfill this centuries-old prophecy."),
 "reflect":"Zechariah's king arrives humbly rather than with worldly displays of power. How does that shape your expectations of how God might work in your own life or circumstances?"},

{"day":180,"book":"Zechariah","ref":"Zechariah 11-14","title":"The One They Have Pierced",
 "chapters":[
  ("Zech 11","A difficult allegory of shepherds describes Israel's rejection of God's true shepherd for thirty pieces of silver, directly echoed in Judas's betrayal of Jesus."),
  ("Zech 12-13","Zechariah prophesies a future day when Jerusalem will look on 'the one they have pierced' and mourn, followed by cleansing from sin and idolatry."),
  ("Zech 14","The book closes with a dramatic vision of the LORD's final, decisive intervention in history, when 'the LORD will be king over the whole earth.'"),
 ],
 "themes":["Old Testament prophecy anticipated even specific details of Christ's betrayal and crucifixion.","God's ultimate plan culminates in His unmistakable, universal reign over the whole earth."],
 "expositor":("kaiser","Kaiser observed that Zechariah 11's prophecy of thirty pieces of silver, and Zechariah 12's prophecy of Jerusalem looking on 'the one they have pierced,' together provide startlingly specific Old Testament anticipation of the very details later recorded in the Gospels' account of Jesus' betrayal and crucifixion."),
 "reflect":"How does the specific, advance detail of these prophecies about Christ's betrayal and death strengthen your confidence in the reliability of the gospel accounts?"},

{"day":181,"book":"Malachi","ref":"Malachi 1-4","title":"Preparing the Way",
 "chapters":[
  ("Mal 1","God confronts Israel's contemptuous, half-hearted worship, offering blemished sacrifices while questioning whether God truly deserves their best."),
  ("Mal 2","Malachi condemns unfaithful priests for corrupting the covenant and rebukes the people's unfaithfulness in marriage and divorce."),
  ("Mal 3","Malachi rebukes the people for withholding their tithes, 'robbing God,' while promising blessing for genuine obedience, and prophesies a coming messenger who will prepare the way before the LORD."),
  ("Mal 4","The Old Testament closes with a promise of coming judgment and healing, and the anticipation of an 'Elijah' figure who will prepare hearts before 'the great and dreadful day of the LORD' -- setting up the New Testament's opening with John the Baptist."),
 ],
 "themes":["Offering God our leftovers rather than our best reveals a deeper problem of contempt, not mere carelessness.","The Old Testament deliberately closes anticipating a future messenger and day of the LORD, setting up the New Testament's opening."],
 "expositor":("kaiser","Kaiser observed that Malachi's closing anticipation of an 'Elijah' figure preparing the way, quoted directly regarding John the Baptist in the Gospels, means the entire Old Testament ends mid-sentence, so to speak -- deliberately incomplete and awaiting the New Testament's opening pages to continue the story."),
 "reflect":"Malachi confronts giving God our leftovers rather than our best. Is there an area of your life -- time, resources, attention -- where God has been getting your leftovers rather than your best?"},

{"day":182,"book":"Review","ref":"Review Day 1","title":"From Creation to Promise",
 "chapters":[
  ("Gen 1-3","Reread the creation and fall accounts that launched the entire Old Testament's storyline of sin and promised redemption."),
  ("Isa 53","Reread the clearest Old Testament portrait of the coming suffering Messiah, now colored by everything you've read since Genesis 3:15 first promised Him."),
 ],
 "themes":["The whole Old Testament traces one unfolding story of promise, failure, and God's persistent redemptive faithfulness.","Rereading familiar passages after months of context often reveals depths missed the first time through."],
 "expositor":("kaiser","Kaiser often summarized the entire Old Testament as the unfolding of a single promise, first given in Genesis 3:15 and developed through Abraham, Moses, David, and the prophets, until it finds its focus in the specific, detailed portrait of Isaiah 53."),
 "reflect":"Journal one sentence: what single truth from the Old Testament has most reshaped how you see God, yourself, or the story leading to Christ?"},

{"day":183,"book":"Review","ref":"Review Day 2","title":"Ready for What Comes Next",
 "chapters":[
  ("Mal 4","Reread the Old Testament's final promise of a coming messenger, sensing how deliberately the story is left open, waiting for its continuation."),
  ("Ps 1","Reread the psalm that opened Israel's prayer book, considering how its call to delight in God's law has, or hasn't, shaped your own habits over these months."),
 ],
 "themes":["The Old Testament closes intentionally incomplete, anticipating the New Testament's continuation of the story.","Finishing a long reading plan well means both giving thanks and prayerfully planning what's next."],
 "expositor":("piper","Piper has often said that Scripture is meant to be a lifetime of 'seeing and savoring' God more fully, not a finished project -- meaning finishing this plan is a milestone to give thanks for, not a finish line to stop at."),
 "reflect":"Give thanks for this season, then prayerfully choose what's next: rereading the New Testament now with this Old Testament background fresh in mind, a deeper study of one Old Testament book, or beginning to read through the whole Bible again from the start."},
]
